import { Agent, GameEngine } from "./game";
import { Hex, GameEvent, Skill } from "../types";
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";
import { RenderPipeline } from "./renderers/RenderPipeline";
import { StatusOrchestrator } from "./renderers/status/StatusOrchestrator"; 
export { Camera };
export class GameRenderer {
    public globalTime: number = 0;
    public grid: GridSystem = new GridSystem();
    public vfx: VFXSystem = new VFXSystem();
    public vfxRenderer: VFXRenderer = new VFXRenderer();
    public unit: UnitRenderSystem = new UnitRenderSystem();
    public statusOrchestrator: StatusOrchestrator = new StatusOrchestrator(); 
    public hud: HUDSystem = new HUDSystem();
    public camera: CameraSystem = new CameraSystem();
    private eventListener: VisualEventListener = new VisualEventListener();
    private pipeline: RenderPipeline = new RenderPipeline(this);
    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
    }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') { this.pipeline.setTransition(t, phase); }
    public getTerrainHeight(q: number, r: number, engine: GameEngine): number { return this.grid.getTerrainHeight(q, r, engine); }
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2, cy = height / 2;
        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;
        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }
    public update(dt: number, engine: GameEngine, externalCameraRef?: any): void {
        this.globalTime += dt;
        this.camera.update(dt);
        if (externalCameraRef?.current) {
            externalCameraRef.current.x = this.camera.x;
            externalCameraRef.current.y = this.camera.y;
        }
        this.pipeline.update(dt, engine); 
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, 
            (x, y) => this.grid.getTerrainHeight(
                this.grid.getHexAtWorldPoint(x, y, engine)?.q || 0,
                this.grid.getHexAtWorldPoint(x, y, engine)?.r || 0,
                engine
            )
        );
        this.hud.update(dt);
    }
    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void { this.eventListener.process(events, engine, this.vfx, this.hud, this.grid, this.camera); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null): void {
        this.pipeline.draw(ctx, engine, camera, highlight, fps, hoveredHex, hoveredSkill, this.globalTime);
    }
}

import React, { useEffect, useRef } from 'react';
import { MatrixConfig } from './types';
interface Drop {
    streamIdx: number;
    pos: number;
    speed: number;
    depth: number;
    seed: number;
}
interface LaneState {
    latestDrop: Drop | null;
}
export const useMatrixRain = (
    canvasRef: React.RefObject<HTMLCanvasElement>, 
    config: MatrixConfig,
    width: number,
    height: number
) => {
    const configRef = useRef(config);
    useEffect(() => { configRef.current = config; }, [config]);
    const timeRef = useRef(0);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = width;
        canvas.height = height;
        if (!config.enabled) {
            ctx.clearRect(0, 0, width, height);
            return;
        }
        const { direction, fontSize, spacing } = configRef.current;
        const isVertical = direction === 'DOWN' || direction === 'UP';
        const totalSize = fontSize + spacing;
        const laneCount = Math.ceil(isVertical ? width / totalSize : height / totalSize);
        const lanes: LaneState[] = Array.from({ length: laneCount }, () => ({ latestDrop: null }));
        let drops: Drop[] = [];
        let animationId: number;
        function createDrop(laneIdx: number, cfg: MatrixConfig): Drop {
            const depthScale = 1.0 + (Math.random() - 0.5) * cfg.depthVariance;
            return {
                streamIdx: laneIdx,
                pos: 0,
                speed: (1 + Math.random() * 2),
                depth: depthScale,
                seed: Math.random() * 1000
            };
        }
        const boundLimit = isVertical ? height : width;
        for (let i = 0; i < laneCount; i++) {
            const d = createDrop(i, configRef.current);
            d.pos = Math.random() * boundLimit;
            drops.push(d);
            lanes[i].latestDrop = d;
        }
        const getStableChar = (laneIdx: number, cellIdx: number, seed: number, charSet: string, volatility: number, time: number) => {
            const len = charSet.length;
            if (len === 0) return "";
            const timeStep = volatility > 0 ? Math.floor(time * volatility * 0.1) : 0;
            const index = Math.abs((laneIdx * 15485863 + cellIdx * 1231 + timeStep * 7919 + Math.floor(seed)) % len);
            return charSet[index];
        };
        const render = () => {
            const cfg = configRef.current;
            timeRef.current++;
            ctx.clearRect(0, 0, width, height);
            ctx.textBaseline = 'top';
            let moveDelta = 0, trailDx = 0, trailDy = 0, startBound = 0, endBound = 0;
            switch(cfg.direction) {
                case 'DOWN':  moveDelta = 1;  trailDx = 0; trailDy = -1; startBound = -100; endBound = height + 100; break;
                case 'UP':    moveDelta = -1; trailDx = 0; trailDy = 1;  startBound = height + 100; endBound = -100; break;
                case 'RIGHT': moveDelta = 1;  trailDx = -1; trailDy = 0; startBound = -100; endBound = width + 100; break;
                case 'LEFT':  moveDelta = -1; trailDx = 1;  trailDy = 0; startBound = width + 100; endBound = -100; break;
            }
            const laneSize = cfg.fontSize + cfg.spacing;
            lanes.forEach((lane, idx) => {
                const spawnOrigin = moveDelta > 0 ? -cfg.fontSize * 5 : (isVertical ? height : width) + cfg.fontSize * 5;
                const gapPixels = (cfg.streamGap * (isVertical ? height : width)) + (cfg.trailLength * cfg.fontSize);
                let canSpawn = false;
                if (!lane.latestDrop) {
                    canSpawn = true;
                } else {
                    const lastPos = lane.latestDrop.pos;
                    if (moveDelta > 0) {
                        if (lastPos > spawnOrigin + gapPixels) canSpawn = true;
                    } else {
                        if (lastPos < spawnOrigin - gapPixels) canSpawn = true;
                    }
                }
                if (canSpawn) {
                    if (cfg.streamGap === 0 || Math.random() < 0.1) {
                        const d = createDrop(idx, cfg);
                        d.pos = spawnOrigin;
                        drops.push(d);
                        lane.latestDrop = d;
                    }
                }
            });
            for (let i = drops.length - 1; i >= 0; i--) {
                const drop = drops[i];
                const effectiveSpeed = drop.speed * cfg.speed * drop.depth;
                drop.pos += effectiveSpeed * moveDelta;
                const isOffScreen = moveDelta > 0 ? (drop.pos > endBound + (cfg.trailLength * cfg.fontSize)) : (drop.pos < endBound - (cfg.trailLength * cfg.fontSize));
                if (isOffScreen) {
                    if (lanes[drop.streamIdx].latestDrop === drop) lanes[drop.streamIdx].latestDrop = null;
                    drops.splice(i, 1);
                    continue;
                }
                const size = Math.max(1, cfg.fontSize * drop.depth);
                ctx.font = `bold ${size}px monospace`;
                const depthAlpha = Math.min(1, Math.max(0.2, (drop.depth - 0.2)));
                const lanePos = drop.streamIdx * laneSize;
                for (let j = 0; j < cfg.trailLength; j++) {
                    const charOffset = j * size;
                    let x = 0, y = 0;
                    if (isVertical) { x = lanePos; y = drop.pos + (charOffset * trailDy); }
                    else { x = drop.pos + (charOffset * trailDx); y = lanePos; }
                    if (x < -size || x > width + size || y < -size || y > height + size) continue;
                    const fade = Math.max(0, (1 - j / cfg.trailLength));
                    const alpha = fade * cfg.textOpacity * depthAlpha;
                    const virtualIdx = Math.floor((isVertical ? y : x) / size);
                    const char = getStableChar(drop.streamIdx, virtualIdx, drop.seed, cfg.charSet, cfg.volatility, timeRef.current);
                    if (j === 0) {
                        ctx.fillStyle = cfg.headColor;
                        if (drop.depth > 0.8) { ctx.shadowColor = cfg.headColor; ctx.shadowBlur = 5 * drop.depth; }
                        else ctx.shadowBlur = 0;
                    } else {
                        ctx.fillStyle = cfg.textColor;
                        ctx.shadowBlur = 0;
                    }
                    ctx.globalAlpha = alpha;
                    ctx.fillText(char, x, y);
                }
            }
            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            animationId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(animationId);
    }, [width, height, config.direction, config.fontSize, config.spacing, config.depthVariance, config.streamGap, config.enabled]); 
};

import { GameEngine } from "../game";
import { GameEvent } from "../../types";
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import { SequenceSystem } from "./visuals/SequenceSystem";
import { EventHUDMapper } from "./visuals/EventHUDMapper";
import { EventVFXMapper } from "./visuals/EventVFXMapper";
import { VisualMath } from "../math/VisualMath";
import { SKILL_SEQUENCES } from "../../data/vfx/SkillSequences";
export class VisualEventListener {
    private hudMapper: EventHUDMapper;
    private vfxMapper: EventVFXMapper;
    constructor() {
        this.hudMapper = new EventHUDMapper();
        this.vfxMapper = new EventVFXMapper();
    }
    public reset() { this.hudMapper.reset(); }
    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        events.forEach(event => {
            this.hudMapper.process(event, engine, hud, grid, camera);
            if (event.type === 'CAST_START' && event.skill) {
                const sequence = SKILL_SEQUENCES[event.skill.id];
                if (sequence) {
                    const target3D = VisualMath.resolveTargetPoint(event.targetId || "", engine);
                    if (target3D.z < -9000) {
                        target3D.x = event.pos.x;
                        target3D.y = event.pos.y;
                        target3D.z = grid.getTerrainHeight(0, 0, engine) + 20; 
                    }
                    SequenceSystem.run(sequence, target3D, engine, vfx, event.sourceId);
                    return; 
                }
            }
            this.vfxMapper.process(event, engine, vfx, grid, camera);
        });
    }
}

